CREATE TABLE IF NOT EXISTS app_state (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS demo_state (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS traffic_events (seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT UNIQUE, ts TEXT, session_id TEXT, client_key TEXT, ip TEXT, method TEXT, path TEXT, status_code INT, user_agent TEXT, header_fp TEXT, stage TEXT, layer TEXT, decision TEXT, risk_score INT, reasons TEXT /*json*/);
CREATE TABLE IF NOT EXISTS sessions (session_id TEXT PRIMARY KEY, client_key TEXT, ip TEXT, user_agent TEXT, header_fp TEXT, first_seen TEXT, last_seen TEXT, request_count INT DEFAULT 0, state TEXT DEFAULT 'SANDBOX', classification TEXT DEFAULT 'UNKNOWN', decision TEXT DEFAULT 'SANDBOX', risk_score INT DEFAULT 0, reasons TEXT DEFAULT '[]' /*json*/, pages TEXT DEFAULT '[]' /*json*/, traps_triggered TEXT DEFAULT '[]' /*json*/, canaries_exposed TEXT DEFAULT '[]' /*json*/, event_ids TEXT DEFAULT '[]' /*json*/);
CREATE TABLE IF NOT EXISTS trap_hits (hit_id TEXT PRIMARY KEY, ts TEXT, session_id TEXT, trap_id TEXT, trap_type TEXT, path TEXT);
CREATE TABLE IF NOT EXISTS canaries (canary_id TEXT PRIMARY KEY, type TEXT, canonical_content TEXT, anchor TEXT, context_terms TEXT, probe_prompts TEXT, sha256 TEXT, content_version TEXT, created_at TEXT, published_at TEXT, status TEXT, placements TEXT);
CREATE TABLE IF NOT EXISTS publications (canary_id TEXT PRIMARY KEY, sha256 TEXT, content_version TEXT, published_at TEXT, placements TEXT);
CREATE TABLE IF NOT EXISTS exposures (exposure_id TEXT PRIMARY KEY, canary_id TEXT, ts TEXT, session_id TEXT, resource TEXT, content_version TEXT, content_sha256 TEXT, client TEXT, request TEXT);
CREATE TABLE IF NOT EXISTS datasets (dataset_id TEXT PRIMARY KEY, role TEXT, path TEXT, sha256 TEXT, records INT, ingested_at TEXT);
CREATE TABLE IF NOT EXISTS probe_runs (probe_id TEXT PRIMARY KEY, started_at TEXT, finished_at TEXT, target TEXT, dataset_id TEXT, dataset_sha256 TEXT, model TEXT /*json name,digest,mode*/, status TEXT);
CREATE TABLE IF NOT EXISTS probe_results (result_id TEXT PRIMARY KEY, probe_id TEXT, canary_id TEXT, prompt TEXT, retrieved TEXT, response_text TEXT, response_sha256 TEXT, latency_ms INT, ts TEXT);
CREATE TABLE IF NOT EXISTS cases (case_id TEXT PRIMARY KEY, run_id TEXT, created_at TEXT, status TEXT, confidence TEXT, primary_canary_id TEXT, session_ids TEXT, probe_ids TEXT, findings TEXT, evidence TEXT, statement TEXT);
CREATE TABLE IF NOT EXISTS evidence_objects (case_id TEXT, name TEXT, sha256 TEXT, bytes INT, local_path TEXT, s3_key TEXT, s3_version_id TEXT, retain_until TEXT, PRIMARY KEY (case_id, name));
CREATE TABLE IF NOT EXISTS forensic_ledger (seq INTEGER PRIMARY KEY, kind TEXT NOT NULL, record TEXT NOT NULL, prev_hash TEXT NOT NULL, hash TEXT NOT NULL, ts TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS prevent_ledger_update BEFORE UPDATE ON forensic_ledger BEGIN SELECT RAISE(ABORT, 'forensic_ledger is append-only: updates prohibited'); END;
CREATE TRIGGER IF NOT EXISTS prevent_ledger_delete BEFORE DELETE ON forensic_ledger BEGIN SELECT RAISE(ABORT, 'forensic_ledger is append-only: deletes prohibited'); END;
CREATE TABLE IF NOT EXISTS session_canary_bindings (canary_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, vector TEXT, ts TEXT, value TEXT);
CREATE TABLE IF NOT EXISTS session_canary_sequences (session_id TEXT PRIMARY KEY, next_seq INTEGER NOT NULL);
